	@ParameterizedTest
	@CsvSource({ "4,1,5,true", "4,2,4,true", "4,2,3,true", "4,5,2,true", "4,8,5,true", "4,5,8,true",
			"4,1,0,true", "1,1,3,true", "256,2,257,true", "4,1,5,false", "4,5,2,false", "4,5,8,false" })
	void changingSetSizeHintPreservesLogicalBatchesAndAllContents(int bulkSize, int initialCount, int actualCount,
			boolean explicit, @TempDir Path directory) throws Exception {
		try (Fixture fixture = new Fixture(directory, bulkSize);
				ExecutorService executor = Executors.newVirtualThreadPerTaskExecutor()) {
			Set<Statement> initial = sizingHintStatements(initialCount);
			Set<Statement> expected = sizingHintStatements(actualCount);
			Set<Statement> concurrent = ConcurrentHashMap.newKeySet();
			concurrent.addAll(initial);
			ChangingSizeSet supplied = new ChangingSizeSet(concurrent);
			Future<?> changed = executor.submit(() -> {
				await(supplied.sizeCaptured);
				try {
					concurrent.retainAll(expected);
					concurrent.addAll(expected);
				} finally {
					supplied.contentsChanged.countDown();
				}
				return null;
			});
			try {
				SailSource source = explicit ? fixture.store.getBackingStore().getExplicitSailSource()
						: fixture.store.getBackingStore().getInferredSailSource();
				try (SailSink sink = source.sink(IsolationLevels.NONE)) {
					sink.approveAll(supplied, Set.of());
					sink.setNamespace("sizing", "urn:sizing-hint:");
					sink.flush();
				}
				changed.get(10, TimeUnit.SECONDS);
				assertEquals(1, supplied.sizeQueries.get(), "one original size query fixes physical execution mode");
				assertWriter(fixture.events, Thread.currentThread(), initialCount <= bulkSize);
				assertEquals(actualCount / bulkSize, fixture.events.alignedWrites.size());
				assertEquals(bulkSize == 1 ? actualCount : actualCount % bulkSize, fixture.events.scalarWrites.size(),
						"the aligned native entry point delegates one-row batches to scalar writes");
				for (AlignedWrite aligned : fixture.events.alignedWrites) {
					assertEquals(bulkSize, aligned.count, "only configured B may select aligned native work");
					assertEquals(bulkSize, aligned.capacity);
				}
				for (int i = 0; i < fixture.events.alignedBuffers.size(); i++) {
					for (int previous = 0; previous < i; previous++) {
						assertNotSame(fixture.events.alignedBuffers.get(previous), fixture.events.alignedBuffers.get(i),
								"each native submission owns distinct ID storage");
					}
				}
				try (RepositoryConnection observer = fixture.repository.getConnection()) {
					Set<Statement> observed = new LinkedHashSet<>();
					try (var result = observer.getStatements(null, null, null, true)) {
						while (result.hasNext()) {
							observed.add(result.next());
						}
					}
					assertEquals(expected, observed);
					assertEquals(explicit ? actualCount : 0, observer.size());
					assertEquals("urn:sizing-hint:", observer.getNamespace("sizing"));
				}
				independentWrite(fixture, "after-sizing-hint");
			} finally {
				supplied.contentsChanged.countDown();
				changed.cancel(true);
			}
		}
	}

	@ParameterizedTest
	@CsvSource({ "2,5", "2,8", "5,2" })
	void enabledSketchCallbacksSurviveHintGrowthTailsAndDuplicates(int initialCount, int actualCount,
			@TempDir Path directory) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,ospc,psoc")
				.setForceSync(false)
				.setSketchEstimatorEnabled(true)
				.setBulkOperationSize(4);
		try (Fixture fixture = new Fixture(directory, config);
				ExecutorService executor = Executors.newVirtualThreadPerTaskExecutor()) {
			SketchBasedJoinEstimator estimator = fixture.store.getBackingStore().getSketchBasedJoinEstimator();
			assertNotNull(estimator);
			try (SailSink seed = fixture.store.getBackingStore().getExplicitSailSource().sink(IsolationLevels.NONE)) {
				seed.approveAll(sizingHintStatements(1), Set.of());
				seed.flush();
			}
			assertEquals(1L, estimator.rebuild());
			assertTrue(estimator.isReady());
			fixture.events.clearWrites();
			Set<Statement> expected = sizingHintStatements(actualCount);
			Set<Statement> concurrent = ConcurrentHashMap.newKeySet();
			concurrent.addAll(sizingHintStatements(initialCount));
			ChangingSizeSet supplied = new ChangingSizeSet(concurrent);
			Future<?> changed = executor.submit(() -> {
				await(supplied.sizeCaptured);
				try {
					concurrent.retainAll(expected);
					concurrent.addAll(expected);
				} finally {
					supplied.contentsChanged.countDown();
				}
				return null;
			});
			try {
				try (SailSink sink = fixture.store.getBackingStore()
						.getExplicitSailSource()
						.sink(IsolationLevels.NONE)) {
					sink.approveAll(supplied, Set.of());
					sink.flush();
				}
				changed.get(10, TimeUnit.SECONDS);
				assertEquals(1, supplied.sizeQueries.get());
				assertWriter(fixture.events, Thread.currentThread(), initialCount <= 4);
				assertEquals(actualCount / 4, fixture.events.alignedWrites.size());
				assertEquals(actualCount % 4, fixture.events.scalarWrites.size());
				assertEquals((double) ((actualCount + 1) / 2),
						estimator.cardinalitySingle(SketchBasedJoinEstimator.Component.P, "urn:sizing:predicate:0"));
				assertEquals((double) (actualCount / 2),
						estimator.cardinalitySingle(SketchBasedJoinEstimator.Component.P, "urn:sizing:predicate:1"));
				try (SailSink duplicates = fixture.store.getBackingStore()
						.getExplicitSailSource()
						.sink(IsolationLevels.NONE)) {
					duplicates.approveAll(expected, Set.of());
					duplicates.flush();
				}
				assertEquals((double) ((actualCount + 1) / 2),
						estimator.cardinalitySingle(SketchBasedJoinEstimator.Component.P, "urn:sizing:predicate:0"));
				assertEquals((double) (actualCount / 2),
						estimator.cardinalitySingle(SketchBasedJoinEstimator.Component.P, "urn:sizing:predicate:1"));
				try (RepositoryConnection observer = fixture.repository.getConnection()) {
					assertVisible(observer, expected);
					assertEquals(actualCount, observer.size());
				}
			} finally {
				supplied.contentsChanged.countDown();
				changed.cancel(true);
			}
		}
	}

