	@ParameterizedTest
	@CsvSource({ "false,false", "false,true", "true,false", "true,true" })
	void sourceOrderAndNestedPublicationKeepOneWriter(boolean inferredFirst, boolean largeFirst,
			@TempDir Path directory) throws Exception {
		try (Fixture fixture = new Fixture(directory, 4)) {
			LmdbSailStore backing = fixture.store.getBackingStore();
			SailSource firstSource = inferredFirst ? backing.getInferredSailSource() : backing.getExplicitSailSource();
			SailSource secondSource = inferredFirst ? backing.getExplicitSailSource() : backing.getInferredSailSource();
			Set<Statement> first = statements("source-first", largeFirst ? 5 : 2);
			Set<Statement> second = statements("source-second", largeFirst ? 2 : 5);
			try (SailClosable outer = firstSource.beginPublication()) {
				try (SailSink sink = firstSource.sink(IsolationLevels.NONE)) {
					sink.approveAll(first, Set.of());
					sink.flush();
				}
				try (SailClosable inner = secondSource.beginPublication();
						SailSink sink = secondSource.sink(IsolationLevels.NONE)) {
					sink.approveAll(second, Set.of());
					sink.setNamespace("nested", "urn:nested:");
					sink.flush();
				}
				assertTrue(fixture.events.commits.isEmpty(), "only the outer publication commits the paired stores");
			}
			assertWriter(fixture.events, Thread.currentThread(), !largeFirst);
			try (RepositoryConnection observer = fixture.repository.getConnection()) {
				for (Statement statement : first) {
					assertTrue(observer.hasStatement(statement, true));
					assertEquals(!inferredFirst, observer.hasStatement(statement, false));
				}
				for (Statement statement : second) {
					assertTrue(observer.hasStatement(statement, true));
					assertEquals(inferredFirst, observer.hasStatement(statement, false));
				}
				assertEquals("urn:nested:", observer.getNamespace("nested"));
			}
		}
	}

