	@ParameterizedTest
	@CsvSource({ "TRACKED,false", "TRACKED,true", "OMITTED,false", "OMITTED,true", "DISABLED,false",
			"DISABLED,true" })
	void realAlignedMapFullPreservesReplayRetryAndDisabledGrowth(Policy policy, boolean prefix,
			@TempDir Path directory) throws Exception {
		try (Fixture fixture = new Fixture(directory, config(policy))) {
			warmIfOmitted(fixture, policy);
			Set<Statement> prior = statements("prior", 2);
			write(fixture, prior);
			fixture.events.clearWrites();
			fixture.events.failContextCall.set(prefix ? 2 : 1);
			Set<Statement> input = statements("aligned-capacity", 4);
			Set<Statement> earlier = prefix ? statements("earlier", 4) : Set.of();
			try (RepositoryConnection writer = fixture.repository.getConnection()) {
				writer.begin();
				writer.add(earlier);
				writer.add(input);
				writer.setNamespace("abandoned", "urn:complete:");
				if (policy == Policy.TRACKED) {
					writer.commit();
					assertEquals(!prefix, fixture.events.starts.getFirst() == Thread.currentThread());
					assertTrue(fixture.events.decisions.getFirst().track);
					try (RepositoryConnection observer = fixture.repository.getConnection()) {
						assertVisible(observer, prior);
						assertVisible(observer, input);
						assertVisible(observer, earlier);
						assertEquals("urn:complete:", observer.getNamespace("abandoned"));
					}
				} else {
					RepositoryException failure = assertThrows(RepositoryException.class, writer::commit);
					assertEquals(!prefix, fixture.events.starts.getFirst() == Thread.currentThread());
					assertFalse(fixture.events.decisions.getFirst().track);
					assertEquals(0, fixture.store.triples.writeTxn);
					assertUnpublished(fixture, input);
					assertUnpublished(fixture, earlier);
					if (policy == Policy.OMITTED) {
						assertPoisoned(writer, failure);
					} else {
						assertNotNull(cause(failure, TripleStore.MapFullException.class));
						assertNull(cause(failure, LmdbTransactionRetryException.class));
					}
					independentWrite(fixture, "aligned-independent");
					writer.rollback();
					Set<Statement> complete = new LinkedHashSet<>(earlier);
					complete.addAll(input);
					retryOnAnotherThread(fixture, writer, complete);
					assertVisible(writer, prior);
				}
			}
		}
	}

